#!/bin/bash\n# Complete Setup and Auto Trading Launch Script\n# This script does everything for you!\n\nset -e\n\necho \"\"\necho \"╔════════════════════════════════════════════════════════════╗\"\necho \"║   🚀 AI Trading Bot - Complete Auto Setup & Launch         ║\"\necho \"╚════════════════════════════════════════════════════════════╝\"\necho \"\"\n\n# Step 1: Check Python\necho \"[Step 1/7] ✓ Checking Python...\"\nif ! command -v python3 &> /dev/null; then\n    echo \"✗ Python 3 not found. Please install Python 3.9+\"\n    exit 1\nfi\necho \"  $(python3 --version)\"\n\n# Step 2: Setup virtual environment\necho \"\"\necho \"[Step 2/7] ✓ Setting up virtual environment...\"\nif [ ! -d \"venv\" ]; then\n    python3 -m venv venv\nfi\nsource venv/bin/activate\necho \"  ✓ Activated\"\n\n# Step 3: Install dependencies\necho \"\"\necho \"[Step 3/7] ✓ Installing dependencies...\"\npip install --upgrade pip -q\npip install -r requirements.txt -q\necho \"  ✓ All dependencies installed\"\n\n# Step 4: Setup configuration\necho \"\"\necho \"[Step 4/7] ✓ Checking configuration...\"\nif [ ! -f \".env\" ]; then\n    cp .env.example .env\n    echo \"  ✓ Created .env file\"\n    echo \"\"\n    echo \"  ⚠️  IMPORTANT: Edit .env with your API keys:\"\n    echo \"     nano .env\"\n    echo \"\"\n    echo \"  Required keys:\"\n    echo \"     - BINANCE_API_KEY\"\n    echo \"     - BINANCE_API_SECRET\"\n    echo \"\"\n    read -p \"  Press Enter after configuring .env...\"\nelse\n    echo \"  ✓ .env already configured\"\nfi\n\n# Step 5: Start Docker\necho \"\"\necho \"[Step 5/7] ✓ Starting Docker containers...\"\nif command -v docker &> /dev/null; then\n    docker-compose up -d\n    echo \"  ✓ Docker containers started\"\n    sleep 5\nelse\n    echo \"  ⚠️  Docker not found. Make sure PostgreSQL is running!\"\nfi\n\n# Step 6: Setup database\necho \"\"\necho \"[Step 6/7] ✓ Setting up database...\"\npython3 << 'PYTHON_EOF'\nfrom app.database import create_tables\ntry:\n    create_tables()\n    print(\"  ✓ Database tables created\")\nexcept Exception as e:\n    print(f\"  ⚠️  Error: {e}\")\nPYTHON_EOF\n\n# Step 7: Load sample data\necho \"\"\necho \"[Step 7/7] ✓ Loading sample market data...\"\npython3 << 'PYTHON_EOF'\nfrom app.database import SessionLocal\nfrom app.models import Candle\nfrom datetime import datetime, timedelta\nimport random\n\ntry:\n    db = SessionLocal()\n    existing = db.query(Candle).first()\n    \n    if existing:\n        print(\"  ✓ Sample data already exists\")\n    else:\n        base_price = 50000.0\n        now = datetime.utcnow()\n        \n        for i in range(200):\n            timestamp = now - timedelta(minutes=(200-i)*5)\n            price_change = random.uniform(-100, 100)\n            \n            candle = Candle(\n                symbol=\"BTCUSDT\",\n                timeframe=\"5m\",\n                timestamp=timestamp,\n                open=base_price + price_change,\n                high=base_price + price_change + 200,\n                low=base_price + price_change - 200,\n                close=base_price + price_change + 50,\n                volume=random.uniform(100, 1000)\n            )\n            db.add(candle)\n            base_price += price_change\n        \n        db.commit()\n        print(\"  ✓ Sample data loaded\")\n    \n    db.close()\nexcept Exception as e:\n    print(f\"  ⚠️  Error: {e}\")\nPYTHON_EOF\n\necho \"\"\necho \"╔════════════════════════════════════════════════════════════╗\"\necho \"║   ✅ Setup Complete!                                       ║\"\necho \"╚════════════════════════════════════════════════════════════╝\"\necho \"\"\necho \"🎯 Choose how to start:\"\necho \"\"\necho \"Option 1: Run API Server (Recommended for testing)\"\necho \"  $ python -m uvicorn app.main:app --reload\"\necho \"\"\necho \"Option 2: Run Auto Trading Bot (Automated trading)\"\necho \"  $ python auto_trader.py\"\necho \"\"\necho \"Option 3: Run Backtest (Test strategy first)\"\necho \"  $ python -c \\\"import asyncio; from app.executors.backtest_engine import BacktestEngine; asyncio.run(BacktestEngine().run_backtest('BTCUSDT'))\\\"\"\necho \"\"\necho \"📖 API Documentation: http://localhost:8000/docs\"\necho \"📊 Dashboard: http://localhost:8000/api/stats/summary\"\necho \"\"\necho \"Press Enter to start API Server...\"\nread\n\necho \"\"\necho \"🚀 Starting API Server...\"\necho \"\"\n\npython -m uvicorn app.main:app --reload --host 0.0.0.0 --port 8000\n", "path": "setup-and-run.sh", "message": "Add complete setup and run script"}